            mc.theWorld.removeEntityFromWorld(freecamEntity.getEntityId());
            mc.thePlayer.setPositionAndRotation(startX, startY, startZ, startYaw, startPitch);
        }
        mc.thePlayer.noClip = false;
        mc.thePlayer.motionY = 0;
        MoveUtil.strafe(0);
